import { createEffect, createSignal, JSXElement } from "solid-js";

import { cn } from "../../utils/cn";

/**
 * The single icon component of croco calc (C10, SB-062, CP-001, AC-019).
 *
 * Icons are Iconify ids written as auditable `set:name` literals (CP-002).
 * Bodies are generated into the block at the bottom of this file by
 * `frontend/vite-plugins/icons.ts`, so the browser never requests
 * the iconify HTTP API — the app works offline and behind a strict CSP
 * (SB-063, AC-021).
 *
 * The rendered `<svg>` is `1em` tall and filled with `currentColor`, so it
 * inherits the OFF / ON / hover / disabled colours of whatever button hosts it
 * with no extra CSS (SB-064). See `frontend/src/styles/icons.scss`.
 *
 * Collection split (C10):
 * - `tabler:*` — the settings bar only (SB-060, SB-061).
 * - `ph:*` (Phosphor) — everywhere else.
 *
 * Adding an icon: list it in `SPEC_ICONS` below (or in the migration table in
 * `frontend/vite-plugins/icons.ts`), then run `npx tsx ./vite-plugins/icons.ts`
 * from `frontend/` to regenerate the bundle.
 */
export type IconProps = {
  /** An iconify id, e.g. `"ph:gear-bold"` or `"tabler:clock"`. */
  icon: string;
  class?: string;
  /** Rotates the icon continuously — replaces font awesome's spin class. */
  spin?: boolean;
  /** Pins the box to `1.25em` wide so labels stay optically aligned (SB-062). */
  fixedWidth?: boolean;
  /** Scales the icon, in `em`, relative to the surrounding text. */
  size?: number;
};

const DEFAULT_VIEW_BOX = "0 0 256 256";

/**
 * Every icon id the requirements name directly, listed so it is bundled before
 * its call site exists. Keep these literal — `frontend/vite-plugins/icons.ts`
 * reads the file as text (CP-002).
 */
export const SPEC_ICONS = [
  // Settings bar — tabler only (SB-060, SB-061, C10).
  "tabler:plus",
  "tabler:x",
  "tabler:divide",
  "tabler:math-1-divide-2",
  "tabler:math-x-divide-y",
  "tabler:decimal",
  "tabler:minus",
  "tabler:plus-minus",
  "tabler:clock",
  "tabler:settings",
  "tabler:share",
  "tabler:trophy",
  "tabler:refresh",
  // The modes-notice strip sits directly under the bar and SB-180 puts
  // `tabler:trophy` in it, so SB-061's no-mixing rule reaches it: its other
  // three icons have to be tabler too. Same class of addition as
  // `tabler:plus-minus` above — forced by a requirement, not a free choice.
  "tabler:chart-bar",
  "tabler:crown",
  "tabler:device-floppy",
  // Shell, test, results, about and modals — phosphor (C10).
  "ph:arrow-counter-clockwise-bold",
  "ph:arrows-clockwise-bold",
  "ph:asterisk-bold",
  "ph:bell-bold",
  "ph:briefcase-bold",
  "ph:bug-bold",
  "ph:calculator-bold",
  "ph:caret-right-bold",
  "ph:chart-line-bold",
  "ph:chat-dots-bold",
  "ph:circle-bold",
  "ph:code-bold",
  "ph:crown-bold",
  "ph:divide-bold",
  "ph:dots-three-bold",
  "ph:envelope-simple-bold",
  "ph:file-text-bold",
  "ph:function-bold",
  "ph:gear-bold",
  "ph:hand-heart-bold",
  "ph:heart-fill",
  "ph:image-bold",
  "ph:info-bold",
  "ph:keyboard-bold",
  "ph:list-bullets-bold",
  "ph:lock-bold",
  "ph:megaphone-bold",
  "ph:palette-bold",
  "ph:plus-minus-bold",
  "ph:question-bold",
  "ph:shield-bold",
  "ph:tag-bold",
  "ph:user-bold",
  "ph:user-circle-bold",
  "ph:warning-bold",
  "ph:x-bold",
] as const;

/** `true` when the id has a bundled body and will therefore render. */
export function hasIcon(icon: string): boolean {
  return ICON_BODIES[icon] !== undefined;
}

/** Every bundled id, sorted. Used by the icon audit and its tests. */
export function bundledIcons(): string[] {
  return Object.keys(ICON_BODIES).sort();
}

export function Icon(props: IconProps): JSXElement {
  const [element, setElement] = createSignal<SVGSVGElement>();

  // The body is raw `<path>` markup from the generated bundle, so it has to go
  // in as markup rather than as children. It is written imperatively because
  // solid types `innerHTML` on HTML elements only, not on SVG ones. The value
  // never comes from user input — it is generated at build time out of the
  // iconify collections and can only ever be geometry.
  createEffect(() => {
    const svg = element();
    if (svg === undefined) return;

    const found = ICON_BODIES[props.icon];
    if (found === undefined && import.meta.env.DEV) {
      // oxlint-disable-next-line no-console
      console.warn(
        `[Icon] "${props.icon}" is not in the generated bundle — add it to Icon.tsx and run \`npx tsx ./vite-plugins/icons.ts\``,
      );
    }
    svg.innerHTML = found ?? "";
  });

  return (
    <svg
      ref={setElement}
      xmlns="http://www.w3.org/2000/svg"
      viewBox={ICON_VIEW_BOXES[props.icon] ?? DEFAULT_VIEW_BOX}
      data-icon={props.icon}
      aria-hidden="true"
      class={cn(
        "icon",
        {
          "icon-fw": props.fixedWidth,
          "icon-spin": props.spin,
        },
        props.class,
      )}
      style={{
        "font-size": props.size !== undefined ? `${props.size}em` : undefined,
      }}
    ></svg>
  );
}

